import { test, expect } from '@playwright/test'

// Tests for the Trail Runner 2 product page (see REQUIREMENTS.md).
// Each test describes the behaviour the shopper should see; selectors use
// roles and accessible names so they reflect what a user perceives.

const PRODUCT_PATH = '/products/trail-runner-2'

test.beforeEach(async ({ page }) => {
  await page.goto(PRODUCT_PATH)
})

test.describe('Entry point', () => {
  test('homepage links to the product page', async ({ page }) => {
    await page.goto('/')
    await page.getByRole('link', { name: 'Trail Runner 2' }).click()
    await expect(page).toHaveURL(/\/products\/trail-runner-2$/)
  })

  test('shows the product name as the main heading', async ({ page }) => {
    await expect(page.getByRole('heading', { level: 1, name: 'Trail Runner 2' })).toBeVisible()
  })
})

test.describe('Store header', () => {
  test('shows the store name', async ({ page }) => {
    await expect(page.getByRole('banner').getByText('Stride', { exact: true })).toBeVisible()
  })

  test('shows how many items are in the cart', async ({ page }) => {
    const cart = page.getByRole('link', { name: /cart/i })
    await expect(cart).toBeVisible()
    await expect(cart).toContainText('0')
  })
})

test.describe('Search', () => {
  test('shows matching suggestions while typing', async ({ page }) => {
    const search = page.getByRole('searchbox', { name: /search/i })
    await search.fill('Trail')
    const suggestions = page.getByRole('listbox', { name: /suggestions/i })
    await expect(suggestions).toBeVisible()
    await expect(suggestions.getByRole('option', { name: /Trail Runner 2/ })).toBeVisible()
  })

  test('shows no suggestions for a term that matches nothing', async ({ page }) => {
    await page.getByRole('searchbox', { name: /search/i }).fill('zzzzzz')
    await expect(page.getByRole('option')).toHaveCount(0)
  })

  test('arrow keys move through suggestions and Enter chooses one', async ({ page }) => {
    const search = page.getByRole('searchbox', { name: /search/i })
    await search.fill('Trail')
    const options = page.getByRole('listbox', { name: /suggestions/i }).getByRole('option')
    await expect(options.first()).toBeVisible()

    await search.press('ArrowDown')
    await expect(options.nth(0)).toHaveAttribute('aria-selected', 'true')
    await search.press('ArrowDown')
    await expect(options.nth(1)).toHaveAttribute('aria-selected', 'true')
    await search.press('ArrowUp')
    await expect(options.nth(0)).toHaveAttribute('aria-selected', 'true')

    const chosen = await options.nth(0).textContent()
    await search.press('Enter')
    await expect(search).toHaveValue(chosen.trim())
    await expect(page.getByRole('listbox', { name: /suggestions/i })).toBeHidden()
  })
})

test.describe('Main menu', () => {
  test('shows the main sections including men, women and kids', async ({ page }) => {
    const menu = page.getByRole('navigation', { name: /main/i })
    for (const section of ['Men', 'Women', 'Kids']) {
      await expect(menu.getByRole('button', { name: section, exact: true })).toBeVisible()
    }
  })

  test('opening a section shows its subsections', async ({ page }) => {
    const menu = page.getByRole('navigation', { name: /main/i })
    await menu.getByRole('button', { name: 'Men', exact: true }).click()
    await expect(menu.getByRole('button', { name: 'Men', exact: true })).toHaveAttribute('aria-expanded', 'true')
    await expect(menu.getByRole('link', { name: /shoes/i })).toBeVisible()
  })

  test('can move into a subsection and back out', async ({ page }) => {
    const menu = page.getByRole('navigation', { name: /main/i })
    await menu.getByRole('button', { name: 'Men', exact: true }).click()
    await menu.getByRole('button', { name: /shoes/i }).click()
    await expect(menu.getByRole('button', { name: /back/i })).toBeVisible()

    await menu.getByRole('button', { name: /back/i }).click()
    await expect(menu.getByRole('link', { name: /shoes/i })).toBeVisible()
    await expect(menu.getByRole('button', { name: 'Women', exact: true })).toBeVisible()
  })
})

test.describe('Path (breadcrumb)', () => {
  test('shows where the shoe sits in the store', async ({ page }) => {
    const path = page.getByRole('navigation', { name: /breadcrumb/i })
    await expect(path.getByRole('link', { name: 'Shop', exact: true })).toBeVisible()
    await expect(path.getByRole('link', { name: 'Trail', exact: true })).toBeVisible()
    await expect(path.getByText('Trail Runner 2', { exact: true })).toBeVisible()
  })

  test('the current step is marked as the current page', async ({ page }) => {
    const path = page.getByRole('navigation', { name: /breadcrumb/i })
    await expect(path.getByText('Trail Runner 2', { exact: true })).toHaveAttribute('aria-current', 'page')
  })

  test('going back to an earlier step navigates to it', async ({ page }) => {
    const path = page.getByRole('navigation', { name: /breadcrumb/i })
    await path.getByRole('link', { name: 'Trail', exact: true }).click()
    await expect(page).not.toHaveURL(/\/products\/trail-runner-2$/)
  })
})

test.describe('Photos', () => {
  const gallery = (page) => page.getByRole('region', { name: /photos/i })
  const mainPhoto = (page) => gallery(page).getByRole('img')

  test('shows exactly one photo at a time', async ({ page }) => {
    await expect(mainPhoto(page)).toHaveCount(1)
    await expect(mainPhoto(page)).toBeVisible()
  })

  test('advances to the next photo automatically', async ({ page }) => {
    const first = await mainPhoto(page).getAttribute('src')
    await expect(mainPhoto(page)).not.toHaveAttribute('src', first, { timeout: 15_000 })
  })

  test('pause stops the photos and resume starts them again', async ({ page }) => {
    await gallery(page).getByRole('button', { name: 'Pause', exact: true }).click()
    const paused = await mainPhoto(page).getAttribute('src')
    await page.waitForTimeout(7_000)
    await expect(mainPhoto(page)).toHaveAttribute('src', paused)

    await gallery(page).getByRole('button', { name: 'Play', exact: true }).click()
    await expect(mainPhoto(page)).not.toHaveAttribute('src', paused, { timeout: 15_000 })
  })

  test('next and previous buttons move between photos', async ({ page }) => {
    await gallery(page).getByRole('button', { name: 'Pause', exact: true }).click()
    const first = await mainPhoto(page).getAttribute('src')

    await gallery(page).getByRole('button', { name: /next/i }).click()
    const second = await mainPhoto(page).getAttribute('src')
    expect(second).not.toBe(first)

    await gallery(page).getByRole('button', { name: /previous/i }).click()
    await expect(mainPhoto(page)).toHaveAttribute('src', first)
  })

  test('after the last photo, next goes back to the first', async ({ page }) => {
    await gallery(page).getByRole('button', { name: 'Pause', exact: true }).click()
    const first = await mainPhoto(page).getAttribute('src')
    const seen = new Set([first])
    let cycled = false

    for (let i = 0; i < 10 && !cycled; i++) {
      await gallery(page).getByRole('button', { name: /next/i }).click()
      const src = await mainPhoto(page).getAttribute('src')
      if (src === first) cycled = true
      else seen.add(src)
    }

    expect(cycled, 'next should eventually return to the first photo').toBe(true)
    expect(seen.size, 'there should be more than one photo').toBeGreaterThan(1)
  })
})

test.describe('Price', () => {
  test('shows the price', async ({ page }) => {
    await expect(page.getByText(/^\$\d+(\.\d{2})?$/).first()).toBeVisible()
  })

  test('the info icon next to the price explains it includes taxes', async ({ page }) => {
    const info = page.getByRole('button', { name: /price info|includes taxes|taxes/i })
    await expect(page.getByText(/includes taxes/i)).toBeHidden()
    await info.hover()
    await expect(page.getByRole('tooltip').or(page.getByText(/includes taxes/i))).toContainText(/includes taxes/i)
  })
})

test.describe('Color', () => {
  const colorChooser = (page) => page.getByRole('group', { name: /color/i })

  test('shows only one color until the shopper changes it', async ({ page }) => {
    await expect(colorChooser(page).getByRole('radio')).toHaveCount(1)
  })

  test('offers blue, black and grey as round swatches once opened', async ({ page }) => {
    await colorChooser(page).getByRole('button', { name: /change color/i }).click()
    for (const color of ['Blue', 'Black', 'Grey']) {
      const swatch = colorChooser(page).getByRole('radio', { name: color, exact: true })
      await expect(swatch).toBeVisible()
      const radius = await swatch.evaluate((el) => {
        const { width } = el.getBoundingClientRect()
        return { width, radius: parseFloat(getComputedStyle(el).borderTopLeftRadius) }
      })
      expect(radius.radius, `${color} swatch should be round`).toBeGreaterThanOrEqual(radius.width / 2)
    }
  })

  test('choosing a color shows only that color', async ({ page }) => {
    await colorChooser(page).getByRole('button', { name: /change color/i }).click()
    await colorChooser(page).getByRole('radio', { name: 'Black', exact: true }).click()

    await expect(colorChooser(page).getByRole('radio')).toHaveCount(1)
    await expect(colorChooser(page).getByText('Black', { exact: true })).toBeVisible()
    await expect(colorChooser(page).getByRole('radio', { name: 'Blue', exact: true })).toBeHidden()
    await expect(colorChooser(page).getByRole('radio', { name: 'Grey', exact: true })).toBeHidden()
  })
})

test.describe('Size', () => {
  // The size picker is the button labelled "Size" (not the "Size guide" button).
  const sizePicker = (page) => page.getByRole('button', { name: /^Size(?! guide)/i })
  const sizeList = (page) => page.getByRole('listbox', { name: /size/i })

  test('the size list is closed until the shopper opens it', async ({ page }) => {
    await expect(sizeList(page)).toBeHidden()
    await sizePicker(page).click()
    await expect(sizeList(page)).toBeVisible()
  })

  test('choosing a size shows only that size and closes the list', async ({ page }) => {
    await sizePicker(page).click()
    await sizeList(page).getByRole('option', { name: 'US 10', exact: true }).click()

    await expect(sizeList(page)).toBeHidden()
    await expect(sizePicker(page)).toContainText('10')
  })

  test('sold-out sizes cannot be picked', async ({ page }) => {
    await sizePicker(page).click()
    const soldOut = sizeList(page).getByRole('option', { name: /sold out/i }).first()
    await expect(soldOut).toBeDisabled()

    const before = await sizePicker(page).textContent()
    await soldOut.click({ force: true }).catch(() => {})
    await expect(sizePicker(page)).toHaveText(before)
  })
})

test.describe('Store availability', () => {
  const grid = (page) => page.getByRole('grid', { name: /store availability/i })

  test('lists nearby stores as rows and sizes as columns', async ({ page }) => {
    await expect(grid(page)).toBeVisible()
    await expect(grid(page).getByRole('row').nth(1).getByRole('rowheader')).not.toBeEmpty()
    await expect(grid(page).getByRole('columnheader', { name: /^US \d+/ }).first()).toBeVisible()
  })

  test('arrow keys move focus between store and size choices', async ({ page }) => {
    const cells = grid(page).getByRole('gridcell')
    await cells.first().focus()
    const firstName = await cells.first().textContent()
    await page.keyboard.press('ArrowRight')
    await expect(cells.nth(1)).toBeFocused()
    expect(firstName).not.toBeNull()
    await page.keyboard.press('ArrowDown')
    await expect(cells.nth(1 + (await grid(page).getByRole('columnheader').count()) - 1)).toBeFocused()
  })

  test('unavailable store-and-size combinations cannot be picked', async ({ page }) => {
    const unavailable = grid(page).getByRole('gridcell').filter({ has: page.getByRole('button', { disabled: true }) }).first()
    await expect(unavailable).toBeVisible()
    await expect(unavailable.getByRole('button')).toBeDisabled()
  })

  test('picking an available store and size selects it for pickup', async ({ page }) => {
    const available = grid(page).getByRole('gridcell').filter({ has: page.getByRole('button').and(page.locator(':not([disabled])')) }).first()
    await available.getByRole('button').click()
    await expect(page.getByText(/pick ?up/i)).toBeVisible()
    await expect(page.getByText(/pick ?up/i)).toContainText(/US \d+/)
  })
})

test.describe('Size guide', () => {
  const guide = (page) => page.getByRole('dialog', { name: /size guide/i })

  test('opens a size chart over the page from next to the size', async ({ page }) => {
    await page.getByRole('button', { name: 'Size guide', exact: true }).click()
    await expect(guide(page)).toBeVisible()
  })

  test('converts a foot length to a size in US or EU', async ({ page }) => {
    await page.getByRole('button', { name: 'Size guide', exact: true }).click()
    await guide(page).getByLabel(/foot length/i).fill('26')

    await guide(page).getByRole('radio', { name: 'US', exact: true }).check()
    await guide(page).getByRole('button', { name: /get my size|find my size|calculate/i }).click()
    await expect(guide(page)).toContainText(/US \d+/)

    await guide(page).getByRole('radio', { name: 'EU', exact: true }).check()
    await guide(page).getByRole('button', { name: /get my size|find my size|calculate/i }).click()
    await expect(guide(page)).toContainText(/EU \d+/)
  })

  test('must be closed before the rest of the page can be used', async ({ page }) => {
    await page.getByRole('button', { name: 'Size guide', exact: true }).click()
    await expect(page.getByRole('button', { name: 'Add to cart' })).toHaveCount(0)

    await guide(page).getByRole('button', { name: 'Close' }).click()
    await expect(guide(page)).toBeHidden()
    await expect(page.getByRole('button', { name: 'Add to cart' })).toBeVisible()
  })
})

test.describe('Quantity', () => {
  const quantity = (page) => page.getByRole('spinbutton', { name: /quantity/i })

  test('starts at one pair', async ({ page }) => {
    await expect(quantity(page)).toHaveValue('1')
  })

  test('can be typed in', async ({ page }) => {
    await quantity(page).fill('3')
    await expect(quantity(page)).toHaveValue('3')
  })

  test('can be changed by one with the plus and minus buttons', async ({ page }) => {
    await page.getByRole('button', { name: /increase quantity/i }).click()
    await expect(quantity(page)).toHaveValue('2')
    await page.getByRole('button', { name: /decrease quantity/i }).click()
    await expect(quantity(page)).toHaveValue('1')
  })

  test('cannot go below one pair', async ({ page }) => {
    await page.getByRole('button', { name: /decrease quantity/i }).click()
    await expect(quantity(page)).toHaveValue('1')
  })
})

test.describe('Delivery date', () => {
  const calendar = (page) => page.getByRole('grid', { name: /calendar|delivery/i })

  test('opens a calendar and moves between days with the keyboard', async ({ page }) => {
    await page.getByRole('button', { name: /delivery date/i }).click()
    await expect(calendar(page)).toBeVisible()

    const day = calendar(page).getByRole('gridcell', { name: /./ }).filter({ hasNot: page.locator('[aria-disabled=true]') }).first()
    await day.focus()
    const before = await page.evaluate(() => document.activeElement?.textContent)
    await page.keyboard.press('ArrowRight')
    const after = await page.evaluate(() => document.activeElement?.textContent)
    expect(after).not.toBe(before)
  })

  test('moves between months', async ({ page }) => {
    await page.getByRole('button', { name: /delivery date/i }).click()
    const heading = calendar(page).locator('xpath=ancestor::*[@role="dialog" or self::section][1]').getByRole('heading')
    const before = await heading.textContent()
    await page.getByRole('button', { name: /next month/i }).click()
    await expect(heading).not.toHaveText(before)
  })

  test('choosing an available day shows the chosen delivery date', async ({ page }) => {
    await page.getByRole('button', { name: /delivery date/i }).click()
    const day = calendar(page).getByRole('gridcell').filter({ hasNot: page.locator('[aria-disabled=true]') }).first()
    const dayLabel = (await day.textContent()).trim()
    await day.click()

    await expect(calendar(page)).toBeHidden()
    await expect(page.getByText(/delivery/i).filter({ hasText: new RegExp(`\\b${dayLabel}\\b`) })).toBeVisible()
  })

  test('unavailable days cannot be chosen', async ({ page }) => {
    await page.getByRole('button', { name: /delivery date/i }).click()
    const unavailable = calendar(page).locator('[aria-disabled=true], [disabled]').first()
    await expect(unavailable).toBeVisible()
    await expect(unavailable).toBeDisabled().or(expect(unavailable).toHaveAttribute('aria-disabled', 'true'))
  })
})

test.describe('Add to cart', () => {
  const addToCart = (page) => page.getByRole('button', { name: 'Add to cart', exact: true })

  test('asks for a size when none is picked', async ({ page }) => {
    await addToCart(page).click()
    await expect(page.getByRole('alert')).toContainText(/select a size|choose a size|pick a size/i)
    await expect(page.getByRole('link', { name: /cart/i })).toContainText('0')
  })

  test('adds the shoe to the cart and confirms it', async ({ page }) => {
    await page.getByRole('button', { name: /^Size(?! guide)/i }).click()
    await page.getByRole('listbox', { name: /size/i }).getByRole('option', { name: 'US 10', exact: true }).click()
    await addToCart(page).click()

    await expect(page.getByRole('status')).toContainText(/added to (your )?cart/i)
    await expect(page.getByRole('link', { name: /cart/i })).toContainText('1')
  })
})

test.describe('Wishlist', () => {
  test('saves and unsaves the shoe with the heart', async ({ page }) => {
    const heart = page.getByRole('button', { name: /wishlist/i })
    await expect(heart).toHaveAttribute('aria-pressed', 'false')

    await heart.click()
    await expect(heart).toHaveAttribute('aria-pressed', 'true')

    await heart.click()
    await expect(heart).toHaveAttribute('aria-pressed', 'false')
  })
})

test.describe('More information', () => {
  const tabs = (page) => page.getByRole('tablist')

  test('details, reviews and shipping are shown side by side', async ({ page }) => {
    const names = ['Details', 'Reviews', 'Shipping']
    const boxes = []
    for (const name of names) {
      const box = await tabs(page).getByRole('tab', { name, exact: true }).boundingBox()
      expect(box, `${name} tab should be visible`).not.toBeNull()
      boxes.push(box)
    }
    expect(Math.abs(boxes[0].y - boxes[1].y)).toBeLessThan(5)
    expect(Math.abs(boxes[1].y - boxes[2].y)).toBeLessThan(5)
    expect(boxes[0].x).toBeLessThan(boxes[1].x)
    expect(boxes[1].x).toBeLessThan(boxes[2].x)
  })

  test('sits below the rest of the product content', async ({ page }) => {
    const tabBox = await tabs(page).boundingBox()
    const addBox = await page.getByRole('button', { name: 'Add to cart', exact: true }).boundingBox()
    const questionsBox = await page.getByRole('heading', { name: /questions/i }).boundingBox()
    expect(tabBox.y).toBeGreaterThan(addBox.y + addBox.height)
    expect(tabBox.y).toBeGreaterThan(questionsBox.y)
  })

  test('shows one section at a time', async ({ page }) => {
    await tabs(page).getByRole('tab', { name: 'Details', exact: true }).click()
    await expect(page.getByRole('tabpanel')).toHaveCount(1)
    await expect(page.getByRole('tabpanel')).toBeVisible()

    await tabs(page).getByRole('tab', { name: 'Reviews', exact: true }).click()
    await expect(page.getByRole('tabpanel')).toHaveCount(1)
    await expect(page.getByRole('tabpanel')).toBeVisible()
    await expect(tabs(page).getByRole('tab', { name: 'Reviews', exact: true })).toHaveAttribute('aria-selected', 'true')
  })
})

test.describe('Questions', () => {
  const faq = (page) => page.getByRole('region', { name: /questions/i })

  test('shows at least three common questions', async ({ page }) => {
    expect(await faq(page).getByRole('button').count()).toBeGreaterThanOrEqual(3)
  })

  test('each answer stays hidden until its question is opened', async ({ page }) => {
    const questions = faq(page).getByRole('button')
    const count = await questions.count()
    for (let i = 0; i < count; i++) {
      const question = questions.nth(i)
      await expect(question).toHaveAttribute('aria-expanded', 'false')
      const answerId = await question.getAttribute('aria-controls')
      const answer = page.locator(`[id="${answerId}"]`)
      await expect(answer).toBeHidden()

      await question.click()
      await expect(question).toHaveAttribute('aria-expanded', 'true')
      await expect(answer).toBeVisible()
    }
  })
})

test.describe('Footer', () => {
  const footer = (page) => page.getByRole('contentinfo')

  test('has customer help, company and social media links', async ({ page }) => {
    for (const heading of ['Customer help', 'Company', 'Social media']) {
      const group = footer(page).getByRole('heading', { name: heading, exact: true })
      await expect(group).toBeVisible()
    }
  })

  test('each footer group has links', async ({ page }) => {
    for (const heading of ['Customer help', 'Company', 'Social media']) {
      const section = footer(page).locator('section, div, nav').filter({ has: page.getByRole('heading', { name: heading, exact: true }) }).last()
      await expect(section.getByRole('link').first()).toBeVisible()
    }
  })
})
